        : fbBuilder.writeList(_ROW_KEYS!.map(fbBuilder.writeString).toList());
    final int? COL_KEYSOffset = _COL_KEYS == null ? null
        : fbBuilder.writeList(_COL_KEYS!.map(fbBuilder.writeString).toList());
    final int? PROVIDER_IDOffset = _PROVIDER_ID == null ? null
        : fbBuilder.writeString(_PROVIDER_ID!);
