        : fbBuilder.writeString(_SOURCE_NAME!);
    fbBuilder.startTable(22);
    fbBuilder.addInt8(0, _KIND?.value);
    fbBuilder.addOffset(1, SCHEMA_NAMEOffset);
    fbBuilder.addOffset(2, SQLOffset);
    fbBuilder.addOffset(3, X_FIELDOffset);
    fbBuilder.addOffset(4, Y_FIELDSOffset);
