    fbBuilder.addUint64(14, _MATCHED);
    fbBuilder.addUint64(15, _STORED);
    fbBuilder.addBool(16, _PARTIAL);
    fbBuilder.addBool(17, _TRUNCATED);
    fbBuilder.addUint32(18, _ELAPSED_MS);
